from common import *

OWL = lambda title, path: {"title": f"Purdue OWL: {title}", "url": "https://owl.purdue.edu/owl/" + path}
L = []

# ---------------------------------------------------------------- Subject-verb agreement
L.append({"id": "subject-verb-agreement", "title": "Subject-verb agreement", "band": "Grades 8–9", "minutes": 30,
 "lede": "A verb has to match its subject. The rule takes ten seconds to learn. Finding the real subject is the skill, and this lesson trains it.",
 "sections": [
  T("## The rule\nA **singular subject** takes a **singular verb**. A **plural subject** takes a **plural verb**.\n\n- The truck **runs**. The trucks **run**.\n- She **is** ready. They **are** ready.\n\nCareful: in the present tense, the **singular** verb is the one that ends in *-s*. Nouns work the opposite way. *The driver drives. The drivers drive.* One *-s* per pair, never two.\n\nNobody gets this wrong in short sentences. The mistakes happen when the subject is **hidden**, **split** or **disguised**. Every section below is one of those disguises."),
  T("## Disguise 1: words in between\nThe verb agrees with the **subject**, not with the noun closest to it.\n\n- The **list** of overdue invoices **is** on your desk. (*list is*, not *invoices are*)\n- The **cost** of the new tires **was** higher than expected.\n\n**Method:** cross out every prepositional phrase (*of the invoices*, *in the yard*, *with the drivers*). What's left is the subject.\n\nPhrases like **along with**, **as well as**, **together with** and **in addition to** don't add to the subject. They're just extra information.\n\n- The **manager**, along with two dispatchers, **was** at the meeting."),
  CHECK("Choose the verb: \"The **box** of brake pads ___ in the shop.\"", ["are", "is"], 1, "Cross out *of brake pads*. **The box is.**"),
  T("## Disguise 2: compound subjects\n- **And** joins subjects into a plural: *The driver **and** the dispatcher **are** on the call.*\n- **Or** and **nor** don't add. The verb agrees with whichever subject is **closer** to it: *Neither the manager nor the **drivers were** told.* *Neither the drivers nor the **manager was** told.*\n\nThe second sentence is correct but sounds odd. When that happens, put the plural subject last. It reads better."),
  T("## Disguise 3: indefinite pronouns\n| Always singular | Always plural | Depends on the noun after *of* |\n|---|---|---|\n| each, every, either, neither, everyone, everybody, anyone, someone, no one, nobody, everything, nothing | both, few, many, several, others | **some, any, none, all, most** |\n\n- **Each** of the trucks **has** a GPS.\n- **Several** of the trucks **have** dash cams.\n- **Some** of the **money is** missing. **Some** of the **trucks are** late.\n\n*None* used to be treated as always singular. Today both *none is* and *none are* are standard. Use *none is* when you mean \"not one\" and *none are* when you mean \"not any of them.\""),
  CHECK("\"Every one of the drivers ___ a clean record.\"", ["have", "has"], 1, "The subject is **every one**, which is singular. *Of the drivers* is crossed out."),
  T("## Disguise 4: the subject comes after the verb\nIn sentences starting with **There** or **Here**, the real subject comes **after** the verb.\n\n- There **are** three loads waiting. (*loads are*)\n- There **is** a problem with the invoice. (*problem is*)\n- Here **come** the inspectors.\n\nIn speech, people say *there's* for everything (\"there's three loads\"). In writing, flip the sentence in your head: *Three loads are there.*"),
  T("## Disguise 5: words that look plural or singular but aren't\n- **Collective nouns** (team, company, jury, family, staff) are **singular** in American English when the group acts as one unit: *The company **is** expanding.* (British English often says *the company are*.)\n- **Amounts treated as one unit** are singular: *Ten thousand dollars **is** a lot. Five miles **is** a long run.*\n- **Nouns ending in -s that are singular:** news, economics, mathematics, physics, measles. *The news **is** bad.*\n- **The number of** = singular. **A number of** = plural. *The number of complaints **is** rising. A number of drivers **have** quit.*\n- **Titles** are singular: *\"Trading in the Zone\" **is** on my list.*"),
  E("Untangle a long sentence", "\"The results of the safety inspection, which covered every truck in the fleet, ___ due Friday.\"",
    ["Cross out *of the safety inspection*.", "Cross out the *which* clause: it's extra information.", "What's left: **The results ___ due Friday.**"], "**are**. *The results are due Friday.*"),
  E("Linking verbs", "\"The biggest problem ___ the brakes.\"",
    ["With *is/are* in the middle, the verb agrees with the **subject** (before it), not the word after it.", "Subject: *the problem*, singular."], "**is**. *The biggest problem is the brakes.* Flip it and it changes: *The brakes are the biggest problem.*"),
  N("Common traps", "- **Each** after a plural subject doesn't make it singular: *The drivers **each** have a key.* (Subject: *drivers*.)\n- **Data** is technically plural (one *datum*), and scientists often still write *the data are*. In everyday and business writing, *the data is* is standard. Pick one and stay consistent.\n- **Who, which, that** take the number of the word they point to. That leads to the hardest agreement question in English. It's in the challenge questions below.")
 ],
 "practice": [
  MC("\"The stack of invoices ___ on the desk.\"", ["is", "are"], 0, "Cross out *of invoices*: **the stack is**."),
  MC("\"The driver and his partner ___ on the road by 5 AM.\"", ["was", "were"], 1, "**And** makes a plural subject."),
  MC("\"Either the drivers or the dispatcher ___ to blame.\"", ["is", "are"], 0, "With **or**, the verb agrees with the closer subject: *dispatcher is*."),
  MC("\"Each of the new trucks ___ a sleeper cab.\"", ["have", "has"], 1, "**Each** is always singular."),
  MC("\"There ___ two loads left in the yard.\"", ["is", "are"], 1, "The subject comes after the verb: *two loads are*."),
  MC("\"The news from the shop ___ good.\"", ["is", "are"], 0, "**News** is singular even though it ends in *-s*."),
  MC("\"A number of drivers ___ asked for the weekend off.\"", ["has", "have"], 1, "**A number of** = several = plural. *The number of* would be singular."),
  MC("\"Most of the fuel ___ gone.\"", ["is", "are"], 0, "**Most** depends on the noun after *of*. *Fuel* can't be counted, so it's singular."),
  MC("\"He is one of those drivers who ___ never late.\"", ["is", "are"], 1,
     "**Who** points to *drivers* (there's a group of drivers who are never late, and he's one of them), so *who are*.",
     level="challenge", hint="Ask: which word does *who* point back to, *one* or *drivers*?"),
  MC("\"He is the only one of the drivers who ___ never late.\"", ["is", "are"], 0,
     "Now **who** points to *the only one*: only one person is never late. So *who is*. One word, *only*, flips the verb.",
     level="challenge", hint="Compare with the previous question. Who exactly is never late here?"),
  MC("\"The CEO, as well as the board members, ___ against the merger.\"", ["is", "are"], 0,
     "**As well as** doesn't make a compound subject. Cross it out: *The CEO is against the merger.*",
     level="challenge", hint="Is *as well as* the same as *and*?"),
  MC("Which sentence is correct?", ["Neither of the offers are good enough.", "The team have won three straight games. (American English)", "Twenty dollars is too much for that.", "There's three trucks in the shop."], 2,
     "An **amount treated as one sum** is singular. *Neither* is singular (*neither is*). American English treats *team* as singular. *There are three trucks.*",
     level="challenge", hint="Three of these break a rule from this lesson. Check each against a disguise."),
 ],
 "sources": [OWL("Subject/Verb Agreement", "general_writing/grammar/subject_verb_agreement.html")]})

# ---------------------------------------------------------------- Pronouns
L.append({"id": "pronouns", "title": "Pronouns", "band": "Grades 8–9", "minutes": 30,
 "lede": "I or me, who or whom, its or it's, he or they: the pronoun choices that make writing sound educated, and the one test that settles almost all of them.",
 "sections": [
  T("## What a pronoun has to do\nA pronoun stands in for a noun so you don't repeat it. To work, it has to do three things:\n\n1. **Point clearly** to one noun (its *antecedent*).\n2. **Agree** with that noun in number.\n3. Be in the right **case**: subject form or object form.\n\nMost pronoun errors break one of those three."),
  T("## Job 1: point clearly\nIf a reader can't tell which noun a pronoun means, the sentence fails, even if the grammar is perfect.\n\n- ✗ *When Mike called Juan, **he** was furious.* (Who was furious?)\n- ✓ *Mike was furious when he called Juan.*\n\n- ✗ *The truck hit the trailer, and **it** was badly damaged.*\n- ✓ *The truck hit the trailer, and the trailer was badly damaged.*\n\nWatch out for a lonely **this**, **that** or **it** pointing at a whole idea:\n\n- ✗ *Fuel went up and two drivers quit. **This** hurt the quarter.*\n- ✓ *Fuel went up and two drivers quit. **These losses** hurt the quarter.*\n\nFix: put a noun after *this*. It forces you to say what you mean."),
  T("## Job 2: agree in number\nA plural noun takes a plural pronoun, and a singular noun takes a singular one: *The **drivers** forgot **their** logs. The **company** filed **its** taxes.* (A company is *it*, not *they*, in formal writing.)\n\nWhat about a singular noun when you don't know the gender? *Every driver must bring ___ license.*\n\n- **Their** (singular *they*) is now accepted by the major style guides, including APA. Writers have used it this way for centuries, Shakespeare included.\n- **His or her** is correct but clunky if repeated.\n- **Make it plural** is often the cleanest: *All drivers must bring their licenses.*"),
  T("## Job 3: choose the right case\n| Subject form (does the action) | Object form (receives it) |\n|---|---|\n| I | me |\n| he, she | him, her |\n| we | us |\n| they | them |\n| who, whoever | whom, whomever |\n\nNobody says *Me went to the store*. Errors happen in **pairs**:\n\n- ✗ *Jake and **me** loaded the truck.*\n- ✗ *The broker called Jake and **I**.*\n\n**The cover-up test:** cover the other person (the words in brackets) and read the sentence with just the pronoun.\n\n- *[Jake and] me loaded the truck* → *Me loaded*? No: **Jake and I loaded the truck.**\n- *The broker called [Jake and] I* → *called I*? No: **called Jake and me.**"),
  CHECK("\"Between you and ___, this deal is bad.\"", ["I", "me"], 1, "**Between** is a preposition, and prepositions take the object form. *Between you and **me**.* \"Between you and I\" is one of the most common errors educated people make."),
  T("## Who vs whom\nSame test, different tool. Answer the question (or rewrite the clause) using **he** or **him**:\n\n- *___ called the broker?* → **He** called. → **Who** called the broker?\n- *___ did you call?* → You called **him**. → **Whom** did you call?\n- *The driver ___ we hired is great.* → We hired **him**. → *The driver **whom** we hired.*\n\n**he → who. him → whom.** Both end in *m*.\n\nIn casual speech, *who* is fine almost everywhere. In formal writing, applications and contracts, get it right."),
  T("## Myself and the apostrophe traps\n**Myself** is only for two jobs: when you're also the subject (*I trained **myself***) or for emphasis (*I fixed it **myself***). Don't use it to sound formal:\n\n- ✗ *Send the invoice to Sarah or **myself**.* ✓ *to Sarah or **me**.*\n\n**Possessive pronouns never take an apostrophe:** *its, yours, hers, ours, theirs, whose.* An apostrophe in a pronoun almost always means a **contraction**:\n\n| Possessive | Contraction |\n|---|---|\n| **its** wheels | **it's** = it is |\n| **whose** truck | **who's** = who is |\n| **their** load | **they're** = they are |\n| **your** call | **you're** = you are |\n\nTest: expand it. If *it is* doesn't fit, it's **its**."),
  E("Than me or than I?", "\"She trains harder than ___.\"",
    ["*Than* compares two clauses, and the second one is usually cut short.", "Finish it: *She trains harder than **I** (do).*"],
    "**I** in formal writing. In speech, *than me* is common and accepted. But notice how meaning can change: *She likes him more than **I*** (more than I like him) vs *more than **me*** (more than she likes me)."),
  E("Whoever vs whomever", "\"Give the keys to ___ needs them.\"",
    ["The preposition *to* tempts you toward *whomever*. Don't trust it.", "The pronoun's case comes from its job **inside its own clause**: *___ needs them*.", "*He* needs them → subject → **whoever**."],
    "**whoever**. The whole clause *whoever needs them* is the object of *to*, but inside the clause, *whoever* is the subject."),
  N("Common traps", "- **Us vs we** before a noun: cover the noun. *We [drivers] deserve a raise* → *We deserve a raise* ✓, so **we drivers**. *They paid us [drivers] late* → *They paid us late* ✓, so **us drivers**.\n- **A company is \"it.\"** *Walmart raised its prices*, not *their prices*, in formal writing.\n- **Ambiguous \"they.\"** *They say the rates are dropping.* Who says? Name the source.")
 ],
 "practice": [
  MC("\"Marcus and ___ split the route.\"", ["me", "I", "myself"], 1, "Cover *Marcus and*: **I** split the route."),
  MC("\"The dispatcher gave the paperwork to Ana and ___.\"", ["I", "me", "myself"], 1, "Cover *Ana and*: gave it to **me**."),
  MC("\"___ is driving the night shift?\"", ["Who", "Whom"], 0, "**He** is driving → *who*."),
  MC("\"The company raised ___ rates in March.\"", ["their", "its", "it's"], 1, "A company is singular: **its**. *It's* means *it is*."),
  MC("Which sentence is correct?", ["The truck lost it's mirror.", "Who's truck is this?", "They're going to need their permits.", "Your going to love this route."], 2, "*They're* = they are; *their* = belonging to them. The others need *its*, *Whose*, *You're*."),
  MC("\"If you have questions, contact Dana or ___.\"", ["myself", "me", "I"], 1, "Cover *Dana or*: contact **me**. *Myself* only works when *I* is also the subject."),
  MC("\"The shipper ___ we work with pays fast.\"", ["who", "whom"], 1, "We work with **him** → *whom*."),
  MC("Which sentence has an **unclear** pronoun?", ["After Leo paid Tom, he left.", "Tom left after Leo paid him.", "After Leo paid Tom, Tom left.", "Leo paid Tom and then left."], 0, "In the first, *he* could be Leo or Tom."),
  MC("\"Give the bonus to ___ finishes first.\"", ["whoever", "whomever"], 0,
     "Inside its own clause, the pronoun is the subject of *finishes*: **he** finishes → *whoever*. The *to* in front doesn't decide it.",
     level="challenge", hint="Look only at the words *___ finishes first*. Is the pronoun doing the action?"),
  MC("\"___ did the broker say would sign the contract?\"", ["Who", "Whom"], 0,
     "Strip out *did the broker say*: **___ would sign the contract?** → *He* would sign → *who*. The inserted clause tricks people into *whom*.",
     level="challenge", hint="Remove the words *did the broker say* and reread."),
  MC("\"___ veterans know the back roads.\"", ["Us", "We"], 1,
     "Cover *veterans*: **We** know the back roads.",
     level="challenge", hint="Try the sentence without *veterans*."),
  MC("\"Revenue fell and costs rose. This forced layoffs.\" What's the best fix?", ["Change *This* to *It*", "Change *This* to *This squeeze*", "Change *This* to *That*", "Nothing; it's clear"], 1,
     "A bare **this** pointing at a whole idea is vague. **This squeeze** names exactly what forced the layoffs. Adding a noun after *this* is the habit of clear writers.",
     level="challenge", hint="What exactly forced the layoffs? Name it."),
 ],
 "sources": [OWL("Pronoun Case", "general_writing/grammar/pronouns/pronoun_case.html"), OWL("Using Pronouns Clearly", "general_writing/grammar/pronouns/index.html"),
             {"title": "APA Style: Singular \"they\"", "url": "https://apastyle.apa.org/style-grammar-guidelines/grammar/singular-they"}]})

# ---------------------------------------------------------------- Misplaced modifiers
L.append({"id": "misplaced-modifiers", "title": "Misplaced and dangling modifiers", "band": "Grades 8–9", "minutes": 26,
 "lede": "A describing word attaches to whatever it's next to. Put it in the wrong spot and your sentence says something absurd, or something you'll have to pay for.",
 "sections": [
  T("## The rule\nA **modifier** is any word or phrase that describes something. Readers attach it to the **nearest** thing it could describe. Put it next to the wrong word and the meaning changes:\n\n- *I sold a truck to a man **with a cracked windshield**.* (The man has a cracked windshield?)\n- *I sold a truck **with a cracked windshield** to a man.* ✓\n\nThere are three kinds of modifier problems: **misplaced**, **dangling** and **squinting**."),
  T("## 1. Misplaced: the small words that change everything\nWords like **only, just, almost, nearly, even, hardly, merely, exactly** limit whatever comes **right after** them. Move one and you change the meaning:\n\n| Sentence | Meaning |\n|---|---|\n| **Only** I lost $200 today. | Nobody else lost money. |\n| I **only** lost $200 today. | (casual, ambiguous) |\n| I lost **only** $200 today. | It was just $200, not more. |\n| I lost $200 **only** today. | Today was the one day I lost. |\n\nIn speech, *I only lost $200* is fine; tone fixes it. In writing, especially contracts and rules, put the word right before the thing it limits. *Drivers are **only** paid for loaded miles* and *Drivers are paid **only** for loaded miles* can end up in an argument."),
  CHECK("Which sentence says the shift was a little under 10 hours?", ["He almost drove for 10 hours.", "He drove for almost 10 hours."], 1,
        "*He **almost** drove* means he nearly drove but didn't. *Drove for **almost** 10 hours* puts *almost* on the number."),
  T("## 2. Dangling: the phrase with nothing to hold\nAn opening phrase like *Driving down I-95,* has no subject of its own. English assumes the **subject right after the comma** is the one doing it.\n\n- ✗ *Driving down I-95, **a deer** jumped in front of the truck.* (The deer was driving?)\n- ✗ *After reviewing the numbers, **the deal** looked bad.* (The deal reviewed the numbers?)\n\nThe modifier *dangles*: the person doing the action is missing from the sentence.\n\n**Two fixes:**\n1. **Make the doer the subject:** *Driving down I-95, **I** saw a deer jump in front of the truck.*\n2. **Give the phrase its own subject:** *While **I** was driving down I-95, a deer jumped in front of the truck.*"),
  T("## The test for danglers\nAfter any opening phrase that ends in a comma, ask: **who is doing the -ing (or the -ed)?** Then check that the answer is the first noun after the comma.\n\n- *To get a CDL, **the test** must be passed.* → Who gets the CDL? Not the test. ✓ *To get a CDL, **you** must pass the test.*\n- *Tired from sparring, **my bed** looked amazing.* → Who was tired? ✓ *Tired from sparring, **I** thought my bed looked amazing.*"),
  CHECK("Which sentence has a dangling modifier?", ["Exhausted after the shift, Ray fell asleep in the cab.", "Exhausted after the shift, the cab was the only place to sleep.", "Ray, exhausted after the shift, fell asleep in the cab."], 1,
        "**The cab** wasn't exhausted. The person who was tired never appears in the sentence."),
  T("## 3. Squinting: the modifier that looks both ways\nA squinting modifier sits between two things it could describe:\n\n- *Drivers who speed **often** get tickets.*\n\nDo drivers who *often speed* get tickets, or do speeders *often get* tickets? Move the word so it can only look one way:\n\n- *Drivers who **often** speed get tickets.*\n- *Drivers who speed get tickets **often**.*"),
  E("Fix a misplaced phrase", "\"The mechanic told me on Monday the truck would be ready.\"",
    ["Ambiguous: did he *tell* me on Monday, or will the truck *be ready* on Monday?", "Put *on Monday* next to the thing it describes."],
    "*On Monday, the mechanic told me the truck would be ready.* **or** *The mechanic told me the truck would be ready on Monday.*"),
  E("Fix a dangler", "\"Having signed the contract, the payment was sent.\"",
    ["Who signed? Not the payment.", "Make the signer the subject."],
    "*Having signed the contract, **we** sent the payment.*"),
  N("Myth: split infinitives", "You may have heard you can't put a word between *to* and a verb: *to **boldly** go*. That's not a real rule. It was invented by 19th-century writers copying Latin, where infinitives are one word and can't be split. Modern style guides accept split infinitives. Sometimes splitting is the only clear option: *We expect profits to **more than** double.* Try un-splitting that."),
  N("Common traps", "- **Limiting words in rules and contracts.** Always place *only* directly before what it limits. Ambiguity costs money.\n- **Passive voice hides danglers.** *Having finished the route, the truck was parked.* Switch to active voice and the doer shows up: *Having finished the route, **she** parked the truck.*")
 ],
 "practice": [
  MC("Which sentence has a **dangling** modifier?", ["Walking into the office, I noticed the coffee was gone.", "Walking into the office, the coffee was gone.", "When I walked into the office, the coffee was gone.", "The coffee was gone when I walked into the office."], 1, "**The coffee** wasn't walking. The person walking never appears."),
  MC("Which sentence means **no one except Kayla** passed the inspection?", ["Kayla only passed the inspection.", "Only Kayla passed the inspection.", "Kayla passed only the inspection.", "Kayla passed the only inspection."], 1, "**Only** sits right before what it limits: *Kayla*."),
  MC("Fix: \"We need a mechanic for the truck with experience.\"", ["We need a mechanic with experience for the truck.", "We need, with experience, a mechanic for the truck.", "With the truck, we need a mechanic with experience.", "No change needed."], 0, "The *mechanic* needs experience, not the truck. Put the phrase next to *mechanic*."),
  MC("\"Drivers who brake hard frequently wear out their pads.\" The problem is…", ["a dangling modifier", "a squinting modifier", "subject-verb agreement", "nothing"], 1, "**Frequently** could describe *brake hard* or *wear out*. It squints both ways."),
  MC("Best fix: \"After eating dinner, the dishes were washed.\"", ["After eating dinner, the dishes got washed.", "After eating dinner, I washed the dishes.", "The dishes, after eating dinner, were washed.", "After eating, dinner and dishes were washed."], 1, "Make the person who ate the subject: **I**."),
  MC("Which sentence says he was **close to** losing $1,000, but didn't?", ["He nearly lost $1,000.", "He lost nearly $1,000."], 0, "*Nearly lost* = he almost lost it. *Lost nearly $1,000* = he lost a bit under $1,000."),
  MC("\"To pass the CDL test, practice is required.\" What's wrong?", ["Nothing", "It's a dangling modifier: practice doesn't pass the test", "It's a split infinitive", "It's a squinting modifier"], 1, "Who passes the test? Fix: *To pass the CDL test, **you** need practice.*"),
  MC("Is \"I want to really understand this\" grammatically wrong?", ["Yes, never split an infinitive", "No, split infinitives are acceptable", "Yes, *really* is misplaced", "Only in British English"], 1, "Split infinitives are a myth, not a rule. Modern style guides allow them."),
  MC("A rule says: \"Drivers will only be reimbursed for meals over $15 with a receipt.\" Which rewrite says receipts are required **and** only meals over $15 count?", ["Drivers will be reimbursed only for meals over $15, and only with a receipt.", "Only drivers will be reimbursed for meals over $15 with a receipt.", "Drivers will be reimbursed for meals only over $15 with a receipt.", "With a receipt, drivers only will be reimbursed for meals over $15."], 0,
     "Each **only** sits directly before what it limits: *for meals over $15* and *with a receipt*. In a rule that costs money, never leave *only* floating.",
     level="challenge", hint="Count the limits the rule needs. Each one needs its own *only*, in the right spot."),
  MC("Which sentence is **correct**?", ["Based on the data, the route is unprofitable.", "Looking at the data, the route seems unprofitable.", "Reviewing the data, we concluded the route is unprofitable.", "Having reviewed the data, the route was dropped."], 2,
     "Only C names who did the reviewing (**we**). B and D dangle. A is common in business writing, but *based on* still has nothing to attach to; careful editors change it to *The data shows the route is unprofitable.*",
     level="challenge", hint="For each opening phrase, ask who is doing it, then look right after the comma."),
  MC("\"The coach told him after the fight he was cutting weight too fast.\" What's the problem?", ["Dangling modifier", "Squinting modifier: *after the fight* could go with *told* or *was cutting*", "Unclear pronoun only", "Nothing"], 1,
     "Did the coach tell him **after** the fight, or was he cutting weight too fast **after** the fight? Fix: *After the fight, the coach told him...*",
     level="challenge", hint="Read *after the fight* with the words before it, then with the words after it."),
  MC("Why can't you un-split *\"We expect sales to more than double\"*?", ["You can: *to double more than*", "Moving *more than* anywhere else breaks the meaning", "Because it's passive", "Because *double* isn't a verb"], 1,
     "*We expect sales more than to double* and *to double more than* both garble it. That's proof the old \"never split\" rule doesn't hold up.",
     level="challenge", hint="Try moving *more than* to two other places and read each version."),
 ],
 "sources": [OWL("Dangling Modifiers and How to Correct Them", "general_writing/mechanics/dangling_modifiers_and_how_to_correct_them.html"),
             OWL("Sentence Clarity", "general_writing/mechanics/sentence_clarity.html")]})

# ---------------------------------------------------------------- Parallel structure
L.append({"id": "parallel-structure", "title": "Parallel structure", "band": "Grades 8–9", "minutes": 26,
 "lede": "Items in a list should match in form. It's the difference between writing that stumbles and writing that hits like a combination.",
 "sections": [
  T("## The rule\nWhen you put items side by side, in a list, a pair or a comparison, give them the **same grammatical form**.\n\n- ✗ *He likes running, lifting and to spar.*\n- ✓ *He likes running, lifting and sparring.*\n- ✓ *He likes to run, lift and spar.*\n\nThe second and third sound right because each item has the same shape. The reader's brain gets the pattern after item one and expects it to continue. Break it and they stumble."),
  T("## Lists\nCheck lists by stacking the items:\n\n*The job involves*\n- *dispatching loads,*\n- *routing drivers, and*\n- ✗ *to bill customers* → ✓ *billing customers*\n\nEvery item has to fit after the opening words: *The job involves billing customers* ✓, but *The job involves to bill customers* ✗.\n\nThis matters most on **résumés**. Every bullet should start with the same verb form, usually past tense: *Managed 12 trucks. Cut fuel costs 9%. Built a load board.* Not *Managed... Responsible for... Building...*"),
  CHECK("Which version is parallel?", ["Before a fight, he cuts weight, hydrates, and is studying film.", "Before a fight, he cuts weight, hydrates, and studies film.", "Before a fight, he is cutting weight, hydrates, and studies film."], 1, "Three present-tense verbs in a row: **cuts, hydrates, studies**."),
  T("## Pairs: both/and, either/or, neither/nor, not only/but also\nThese are **correlative conjunctions**: they come in two parts. Whatever comes right after the first part must match whatever comes right after the second.\n\n- ✗ *She **not only** drives trucks **but also** she fixes them.* (verb ... clause)\n- ✓ *She **not only** drives trucks **but also** fixes them.* (verb ... verb)\n\n- ✓ ***Either** you sign today **or** the price goes up tomorrow.* (clause ... clause)\n- ✗ *We can **either** pay cash **or** a loan.* (verb ... noun)\n- ✓ *We can **either** pay cash **or** take a loan.* (verb ... verb)\n\nPlace the first word carefully. It decides what the second half has to match."),
  T("## Comparisons\nThings you compare must be the same kind of thing.\n\n- ✗ *Paying cash is cheaper than **to finance**.* ✓ *Paying cash is cheaper than **financing**.*\n- ✗ *Our rates are lower than **Swift**.* (comparing rates to a company)\n- ✓ *Our rates are lower than **Swift's**.* or *than **those of** Swift.*\n\nThat second one is called a **faulty comparison**, and it's everywhere in ads and business writing. Compare rates to rates, not rates to companies."),
  CHECK("\"A fighter's cardio matters more than ___.\"", ["how hard he punches", "a fighter's punching power", "to punch hard", "when he punches hard"], 1,
        "Compare like to like: *a fighter's cardio* vs *a fighter's punching power*. Noun phrase to noun phrase."),
  T("## Why it matters: rhythm and power\nParallel structure isn't just correct. It's how the most memorable lines in history are built:\n\n- *I came, I saw, I conquered.* (Julius Caesar)\n- *...government **of** the people, **by** the people, **for** the people...* (Lincoln)\n- *Ask not what your country can do for you; ask what you can do for your country.* (John F. Kennedy)\n\nGroups of **three** parallel items (a *tricolon*) feel complete. Two parallel halves that flip (like Kennedy's) are called *antithesis*. Use both when you want a line to land."),
  E("Fix a whole sentence", "\"The new dispatcher is fast, organized and has a lot of experience.\"",
    ["Stack it: *is fast / is organized / is has a lot of experience*. The third one breaks.", "The third item breaks the pattern. Turn it into an adjective."], "*The new dispatcher is fast, organized and experienced.*"),
  E("Fix a clause pair", "\"He told us that the load was late and to call the broker.\"",
    ["*that the load was late* is a clause. *to call the broker* is an infinitive.", "Make both *that* clauses."], "*He told us **that** the load was late and **that** we should call the broker.*"),
  N("Repeat little words consistently", "With a series of phrases, either repeat the small word (*to, in, for, the, that*) every time, or use it only once:\n- ✓ *in the morning and in the evening* or *in the morning and evening*\n- ✗ *in the morning and the evening* (mixed: is *the evening* a separate thing?)\n\nRepeating it adds clarity and weight. Lincoln repeated *the people* three times on purpose.")
 ],
 "practice": [
  MC("Which sentence is parallel?", ["I like trading, training, and to read.", "I like trading, training, and reading.", "I like to trade, training, and reading.", "I like trading, to train, and reading."], 1, "Three *-ing* forms."),
  MC("\"She is smart, ambitious and ___.\"", ["she works hard", "has a strong work ethic", "hardworking", "working hard"], 2, "Adjective, adjective, **adjective**."),
  MC("Which uses **not only... but also** correctly?", ["He not only trades futures but also he coaches.", "He not only trades futures but also coaches.", "Not only he trades futures but also coaches.", "He trades not only futures but also coaches."], 1, "Verb after each part: *trades... coaches*. D says he trades coaches."),
  MC("Fix the comparison: \"Our delivery times are faster than FedEx.\"", ["faster than FedEx is", "faster than FedEx's", "faster than with FedEx", "No change needed"], 1, "Compare **times** to **times**: *than FedEx's* (delivery times)."),
  MC("Which résumé section is parallel?", ["Managed 10 drivers. Responsible for payroll. Cut costs 12%.", "Managed 10 drivers. Ran payroll. Cut costs 12%.", "Managing 10 drivers. Ran payroll. Cost cutting of 12%.", "Managed 10 drivers. Payroll. Cutting costs 12%."], 1, "Every bullet starts with a past-tense verb."),
  MC("\"We can either renegotiate the rate ___.\"", ["or the load gets rejected", "or reject the load", "or rejection of the load", "or rejecting the load"], 1, "*either* **renegotiate** ... *or* **reject**: verb and verb."),
  MC("Which line is a **tricolon**?", ["Train hard.", "Train hard, eat clean, sleep early.", "Training is hard and eating clean is too.", "If you train hard, you win."], 1, "Three parallel commands."),
  MC("\"Driving at night is harder than ___ during the day.\"", ["to drive", "driving", "you drive", "drive"], 1, "*Driving* ... *driving*."),
  MC("Which sentence is correct?", ["The rules for Asia are stricter than NY.", "The rules for Asia are stricter than for NY.", "The rules for Asia are stricter than NY's rules are for it.", "Asia's rules are stricter than NY session."], 1,
     "Compare rules to rules. *Than for NY* repeats the preposition, so it's clearly *the rules for NY*. A compares rules to a city.",
     level="challenge", hint="What exactly is being compared to what?"),
  MC("Which version uses **neither/nor** correctly?", ["Neither the broker called nor emailed.", "The broker neither called nor emailed.", "The broker neither called nor did he email.", "Neither did the broker call nor email."], 1,
     "*neither* **called** *nor* **emailed**: two past-tense verbs, both after their connector.",
     level="challenge", hint="Look at the word right after *neither* and right after *nor*."),
  MC("\"The plan is to cut costs, raising rates and that we hire two drivers.\" Best fix?", ["The plan is to cut costs, to raise rates and to hire two drivers.", "The plan is cutting costs, raising rates and that we hire two drivers.", "The plan is to cut costs, raise rates and hiring two drivers.", "The plan: to cut costs, raising rates, hire drivers."], 0,
     "Three infinitives: **to cut, to raise, to hire**. Repeating *to* each time also adds weight.",
     level="challenge", hint="Pick the form of the first item and make the other two match."),
  MC("Kennedy's line *\"Ask not what your country can do for you; ask what you can do for your country\"* uses parallel structure plus…", ["a dangling modifier", "antithesis: the halves flip", "a faulty comparison", "a tricolon"], 1,
     "The two halves have the same shape, but the roles swap (*country → you*, *you → country*). That flip is **antithesis**.",
     level="challenge", hint="Compare who does what in each half."),
 ],
 "sources": [OWL("Parallel Structure", "general_writing/mechanics/parallel_structure.html")]})

# ---------------------------------------------------------------- Verb tense consistency
L.append({"id": "verb-tense-consistency", "title": "Verb tense consistency", "band": "Grades 8–9", "minutes": 30,
 "lede": "Pick a timeline and stay on it. When time really does shift, use the tenses built to show exactly when things happened.",
 "sections": [
  T("## The rule\nChoose a main tense, usually **past** for stories and **present** for facts and explanations, and stay in it. Change tense **only when the time actually changes**.\n\n- ✗ *I **walked** into the gym and the coach **tells** me to wrap up.*\n- ✓ *I **walked** into the gym and the coach **told** me to wrap up.*\n\nShifting for no reason makes readers feel the ground move under them. They can't tell what happened when."),
  T("## The tenses you need\n| Tense | Form | Use it for |\n|---|---|---|\n| Simple present | *I trade* | habits, facts, general truths |\n| Simple past | *I traded* | finished actions at a specific time |\n| Present perfect | *I **have** traded* | past actions that still matter now, or no specific time |\n| Past perfect | *I **had** traded* | something that happened **before** another past event |\n| Future | *I **will** trade* | what's coming |\n| Progressive | *I **was** trading* | an action in progress |\n\nThe two **perfect** tenses are the precision tools. Most tense problems come from not using them, or using them wrong."),
  T("## Past perfect: the past before the past\nWhen you're already telling a story in the past and need to reach **further back**, use *had* + past participle:\n\n- *By the time I **got** to the dock, the load **had** already **left**.*\n\nThe load left first, then I got there. Without *had*, the order is unclear: *By the time I got to the dock, the load already left* sounds like they happened at the same time.\n\nUse it only when order matters. Once the order is clear, you can return to simple past."),
  CHECK("\"When the market opened, I ___ my levels.\" (You marked them before the open.)", ["already marked", "had already marked", "have already marked", "will mark"], 1,
        "Marking the levels happened **before** the open, which is itself in the past. That's **past perfect**: *had marked*."),
  T("## Present perfect vs simple past\n- **Simple past** = finished, at a **specific** time: *I **drove** to Atlanta **yesterday**.*\n- **Present perfect** = no specific time, or still connected to now: *I **have driven** to Atlanta many times.* *She **has worked** here since 2019.* (She still works here.)\n\nThe classic mistake is mixing present perfect with a specific past time:\n\n- ✗ *I **have seen** him **yesterday**.* ✓ *I **saw** him yesterday.*\n\nIf the sentence has a past time stamp (*yesterday, last week, in 2020, at 9 AM*), use **simple past**."),
  T("## Present tense for writing about texts and data\nWhen you write about what a book, study, film or chart **says**, use the present tense, because the text still says it every time you open it:\n\n- *In \"Trading in the Zone,\" Douglas **argues** that consistency **comes** from accepting risk.*\n- *The data **shows** that losses **cluster** after big wins.*\n\nBut the **author's actions** in history stay past: *Douglas **wrote** the book in 2000.*"),
  T("## If-sentences (conditionals)\n| Type | Example | Meaning |\n|---|---|---|\n| Real | *If I **train**, I **win**.* | general truth |\n| Likely future | *If I **train**, I **will win**.* | possible |\n| Unreal present | *If I **were** heavier, I **would** fight at 170.* | not true now |\n| Unreal past | *If I **had trained**, I **would have won**.* | didn't happen |\n\nTwo rules people break:\n- Unreal present uses **were** for everyone: *If I **were** you*, *if he **were** taller*. (This is the subjunctive.)\n- Unreal past: **had** goes in the *if* half. ✗ *If I **would have known**, I would have called.* ✓ *If I **had known**, I would have called.*"),
  E("Fix a shifting paragraph", "\"I entered the trade at the level. Price swept the low and then it reverses. I take profit at 2R and logged it.\"",
    ["The story is in the past (*entered, swept, logged*).", "*reverses* and *take* jump to present for no reason."], "*I entered the trade at the level. Price swept the low and then **reversed**. I **took** profit at 2R and logged it.*"),
  T("## Irregular verbs that trip people up\n| Base | Past | Past participle (with *have/had*) |\n|---|---|---|\n| go | went | **gone** (✗ *have went*) |\n| see | saw | seen (✗ *I seen it*) |\n| drink | drank | drunk |\n| run | ran | run |\n| lie (recline) | **lay** | lain |\n| lay (put down) | laid | laid |\n\n**Lie vs lay** is the hardest pair in English: *lay* is both the present of *put down* and the past of *recline*. *Today I **lie** down. Yesterday I **lay** down. Lay the keys on the table.*\n\nAnd one spelling error from speech: it's ***should have***, ***could have***, ***would have***, never *should of*. *Should've* sounds like *should of*, which is where the mistake comes from."),
  N("Common traps", "- **Reported speech** usually shifts back: *He said he **was** tired.* If it's still true, present is fine: *She said the market **opens** at 9:30.*\n- **\"Was\" vs \"were\" after if:** *If I **was** late, I'm sorry* (real possibility: maybe I was) is correct. *If I **were** you* (impossible: I'm not you) needs *were*.")
 ],
 "practice": [
  MC("\"Yesterday the broker calls and ___ the rate.\" Fix the whole sentence:", ["Yesterday the broker calls and cuts the rate.", "Yesterday the broker called and cut the rate.", "Yesterday the broker called and cuts the rate.", "Yesterday the broker has called and cut the rate."], 1, "*Yesterday* = past. Both verbs past: **called, cut**."),
  MC("\"By the time I got there, the driver ___.\"", ["left", "has left", "had left", "leaves"], 2, "Leaving happened before I got there: **past perfect**."),
  MC("Which is correct?", ["I have seen that setup last week.", "I saw that setup last week.", "I have saw that setup last week.", "I seen that setup last week."], 1, "*Last week* is a specific past time: **simple past**."),
  MC("\"She ___ here since 2021.\" (She still works here.)", ["worked", "has worked", "had worked", "works"], 1, "Started in the past, still true: **present perfect**."),
  MC("\"If I ___ you, I'd take the deal.\"", ["was", "were", "am", "would be"], 1, "Unreal present: **were**, for every subject."),
  MC("\"If I ___ about the news, I wouldn't have traded.\"", ["would have known", "had known", "knew", "have known"], 1, "Unreal past: **had known** in the *if* half."),
  MC("Writing about an article: \"In the article, the author ___ that sleep speeds up recovery.\"", ["argued", "argues", "had argued", "will argue"], 1, "Use **present** for what a text says."),
  MC("Which is correct?", ["I should of checked the news.", "I should have checked the news.", "I should had checked the news.", "I should checked the news."], 1, "**Should have**. *Should of* is a spelling of how *should've* sounds."),
  MC("\"Yesterday I was so tired I ___ down at 6 PM.\"", ["laid", "lay", "lied", "layed"], 1,
     "Past of **lie** (recline) is **lay**. *Laid* is the past of *lay* (put something down): *I laid the keys on the table.*",
     level="challenge", hint="Are you putting something down, or reclining yourself?"),
  MC("Which sentence uses tense correctly to show order?", ["When I checked the chart, price already broke the high.", "When I checked the chart, price had already broken the high.", "When I check the chart, price had already broke the high.", "When I had checked the chart, price already breaks the high."], 1,
     "The break happened **before** the check: *had broken*. Note the participle is *broken*, not *broke*.",
     level="challenge", hint="Which happened first? Then check the past participle of *break*."),
  MC("A trade report says: \"The data showed that losses cluster after big wins.\" What should a careful writer change?", ["*showed* → *shows*, since the data still says it", "*cluster* → *clustered*", "Both verbs to future", "Nothing"], 0,
     "What a source or dataset **says** goes in the present: *the data **shows** that losses **cluster***. Keep *showed* only if you mean a specific past analysis that's no longer current.",
     level="challenge", hint="Does the data stop saying this after you read it?"),
  MC("Which sentence is correct?", ["If I was the coach, I'd change the game plan.", "If I were the coach, I'd change the game plan.", "If I would be the coach, I'd change the game plan.", "If I am the coach, I'd change the game plan."], 1,
     "You're not the coach, so it's unreal: **were**. *If I was* is common in speech, but *were* is standard for imagined situations.",
     level="challenge", hint="Is this a real possibility, or an imagined one?"),
 ],
 "sources": [OWL("Verb Tense Consistency", "general_writing/grammar/verb_tenses/verb_tense_consistency.html")]})

